import { Injectable, computed, signal } from '@angular/core';

export interface CartItem { id: string; priceMinor: number; quantity: number; }

@Injectable({ providedIn: 'root' })
export class CartService {
  private readonly itemsState = signal<CartItem[]>([]);
  readonly items = this.itemsState.asReadonly();
  readonly totalMinor = computed(() =>
    this.items().reduce((sum, x) => sum + x.priceMinor * x.quantity, 0)
  );
  add(item: CartItem): void {
    this.itemsState.update(current => [...current, item]);
  }
}

