import { Component, input, output } from '@angular/core';

export interface Appointment {
  id: string;
  clinician: string;
  startLabel: string;
}

@Component({
  selector: 'app-appointment-card',
  standalone: true,
  template: `
    <article>
      <h2>{{ appointment().clinician }}</h2>
      <p>{{ appointment().startLabel }}</p>
      <button type="button" (click)="cancelRequested.emit(appointment().id)">
        Request cancellation
      </button>
    </article>
  `
})
export class AppointmentCardComponent {
  readonly appointment = input.required<Appointment>();
  readonly cancelRequested = output<string>();
}

// FILE: src/app/appointment-page.component.ts
import { Component } from '@angular/core';
import { AppointmentCardComponent, Appointment } from './appointment-card.component';

@Component({
  selector: 'app-appointment-page',
  standalone: true,
  imports: [AppointmentCardComponent],
  template: `
    <app-appointment-card
      [appointment]="item"
      (cancelRequested)="onCancel($event)" />
    <p role="status">{{ message }}</p>
  `
})
export class AppointmentPageComponent {
  readonly item: Appointment = { id: 'appt-7', clinician: 'Dr Rao', startLabel: 'Tomorrow 10:00' };
  message = '';
  onCancel(id: string): void {
    this.message = `Cancellation requested for ${id}`;
  }
}

